"""``workpeg ui verify``: check a built peg UI as hostile, against its SDK.

Nothing a developer built goes live (owner, 2026-11-02). Workpeg is to build
a released peg itself, and then this checker reads what came out as if the
builder had been broken into: design section 4, stage 2. That builder and
its publisher do not exist yet; until they do, this is what a hand publish
runs on a clean build from the peg's source. It is shipped in the SDK so
that a developer can run the same check on their own build, and so that the
publisher can run it again, in a process that runs no developer code, before
anything is published.

WHAT A PASS MEANS, AND WHAT IT CANNOT. Every SDK file and the page are
compared byte for byte, but ``app.js`` differs for every peg, so it is only
parsed and scanned for the known spellings of sinks. Hand-written
JavaScript that spells a sink another way (``body["inner" + "HTML"]``)
passes. So a pass means the dist is a shape this SDK's build allows, never
that its JavaScript came from the compiler: it must never be the gate for a
dist somebody else built, only for Workpeg's own build or an operator's
clean build from source. ``public/`` files are judged by their names, so a
host must serve each with the ``Content-Type`` its suffix names and
``X-Content-Type-Options: nosniff``. A publisher passes ``namespace`` every
time, since without it a dist built as another peg passes, and uploads the
bytes this reader read (``Report.files`` carries their digests), never what
another tar reader makes of the same archive.

It reads a dist folder, or a plain tar of one, and never follows a link,
opens a device or extracts anything. It checks, each as its own named check:

``read``
    Every entry is a regular file or a folder with a plain ASCII name, no
    link of either kind, no device or FIFO, no ``..``, no absolute path, no
    duplicate and no two names that differ only in case, within
    :data:`MAX_FILES` entries and :data:`MAX_BYTES` bytes. In a tar, each
    entry has a plain ustar header, after at most PAX headers that carry
    only times.
``files``
    Every file is one the build writes, or a ``public/`` file of a type on
    the allow-list. ``index.html`` is the only HTML, and the only scripts
    are the SDK's own.
``build.json``
    The record the build wrote says this SDK built it, with chrome ``auto``,
    and holds the page inputs and nothing else.
``inputs``
    Those inputs describe these files: the ``?v=`` hash is the hash of the
    bundles, ``rtc.js`` is there exactly when the page uses it, and the icon
    sheet is the one the page links.
``index.html``
    The page is, byte for byte, what this SDK's own ``_gen_html`` writes
    for those inputs.
``page``
    The page's markup, read on its own: one script policy equal to
    ``SCRIPT_POLICY`` before anything else, no ``data-chrome``, no inline
    script or handler, and the scripts ``/workpeg-runtime.js``, ``/rtc.js``
    only when the dist carries it, and ``/app.js``, in that order.
``sdk files``
    Every file the SDK owns (the runtime, ``ai.js``, ``scaffold.js``,
    ``editor.js``, ``rtc.js``, ``pegment.css``, the fonts) matches this
    SDK's digest list, and none the build always writes is missing.
``icons.css``
    Every rule in it is a byte-identical rule of this SDK's icon sheet.
``app.js``
    It parses (``node --check``), and it names none of the known sinks.
    Defence in depth only (see above).

Every parser here is linear in what it reads, or capped before it reads:
a hostile dist must not hold the verifier, and the build or publish
waiting on it.
``manifest.json``
    When there is one, it is a JSON object the platform will read.

Only the SDK installed here can be checked against: its digest list is
computed from the files this package carries, by the same function the build
writes them with (:func:`workpeg.ui.build._sdk_bundles`), and its page
template is its own ``_gen_html``. Workpeg's verifier, which checks every
target from 0.150.0 with one current SDK, takes each target's digest list
from that target's builder image, where :func:`digest_list` (``workpeg ui
verify --digests``) writes it when the image is built.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
import stat
import subprocess
import tarfile
import tempfile
from dataclasses import dataclass, field
from html.parser import HTMLParser
from pathlib import Path

from workpeg.ui import build

__all__ = [
    "CHECKS", "MAX_BYTES", "MAX_FILES", "Report", "VerifyError",
    "digest_list", "verify",
]

#: The most entries (files and folders) a dist may hold. The upload cap.
MAX_FILES = 5000

#: The most bytes a dist's files may add up to, unpacked. The upload cap; a
#: build with the whole 26 MB icon sheet bundled still fits.
MAX_BYTES = 60 * 1024 * 1024

#: The most ``build.json`` may hold. A real one is under 1 KB.
MAX_RECORD_BYTES = 64 * 1024

#: The most ``index.html`` may hold before its markup is parsed. A real page
#: is about 1 KB (Phone's is 814 bytes, the playground's 1,018), and
#: html.parser is quadratic on a run of unclosed tags, so a page of the
#: dist's whole budget would hold the verifier for days.
MAX_PAGE_BYTES = 8 * 1024

#: The PAX keys a tar entry may carry: times only, which Python's tarfile
#: writes for every file added from disk. Every other key can rename an
#: entry, move where it ends or say what another reader reads differently.
_PAX_TIMES = frozenset({"mtime", "atime", "ctime"})

#: The checks, in the order they run and are reported.
CHECKS = (
    "read", "files", "build.json", "inputs", "index.html", "page",
    "sdk files", "icons.css", "app.js", "manifest.json",
)

#: Files at the site root a build writes that are not in the digest list,
#: because they differ from peg to peg.
_PAGE_FILES = frozenset({
    "index.html", "app.js", "build.json", "manifest.json", "icons.css",
})

#: What may ship from ``public/``: the build's allow-list, less ``.pdf``,
#: which stays refused until a PDF's script has been measured (decision 15,
#: 2026-11-12), as the CDN route already refuses it.
_SHIPPABLE = build.PUBLIC_SUFFIXES - {".pdf"}

#: The keys of ``build.json`` and of its ``page``, exactly.
_RECORD_KEYS = frozenset({"format", "sdk", "page"})
_PAGE_KEYS = frozenset({
    "app_name", "peg_namespace", "ver", "uses_icons", "icons_href",
    "icons_ver", "fonts", "chrome_source", "uses_chrome", "uses_rtc",
})
_BOOL_KEYS = ("uses_icons", "uses_chrome", "uses_rtc")

_HASH8 = re.compile(r"[0-9a-f]{8}\Z")
_VERSIONISH = re.compile(r"[0-9A-Za-z.+-]{1,64}\Z")

#: Names a browser will run markup or code through, in the shapes compiled
#: JavaScript would name them: as a property after a dot, or as the string
#: inside a bracket, which is how the compiler writes property access.
#: A developer's text that holds one of these words in a sentence is not
#: matched, except ``javascript:``, which is refused wherever it appears.
_SINKS = (
    ("innerHTML", re.compile(
        r"""(?:\.|\[\s*["'`])\s*innerHTML\b""")),
    ("outerHTML", re.compile(
        r"""(?:\.|\[\s*["'`])\s*outerHTML\b""")),
    ("insertAdjacentHTML", re.compile(
        r"""(?:\.|\[\s*["'`])\s*insertAdjacentHTML\b""")),
    ("srcdoc", re.compile(r"""(?:\.|\[\s*["'`])\s*srcdoc\b""")),
    ("document.write", re.compile(
        r"""\bdocument\s*(?:\.|\[\s*["'`])\s*write(?:ln)?\b""")),
    ("eval", re.compile(
        r"""\beval\s*\(|\[\s*["'`]eval["'`]\s*\]""")),
    ("new Function", re.compile(
        r"""\bnew\s+Function\b|\bFunction\s*\(|\[\s*["'`]Function["'`]\s*\]""")),
    ("javascript:", re.compile(r"javascript\s*:", re.IGNORECASE)),
    ("the dev live-reload client", re.compile(r"_workpeg_reload")),
    ("a timer given a string", re.compile(
        r"""\bset(?:Timeout|Interval)\s*\(\s*["'`]""")),
    ("a script element", re.compile(
        r"""\bcreateElement(?:NS)?\s*\([^)]{0,200}?["'`]\s*script\b""",
        re.IGNORECASE)),
    ("import()", re.compile(r"(?<![\w$.])import\s*\(")),
    ("Reflect", re.compile(r"\bReflect\s*(?:\.|\[)")),
)

#: Where ``node --check`` gives up on one file.
_NODE_TIMEOUT = 60


class VerifyError(Exception):
    """The check cannot be run as asked (a target this SDK does not hold).
    Not a verdict on the dist."""


@dataclass
class Check:
    name: str
    problems: "list[str]" = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.problems


@dataclass
class Report:
    """What :func:`verify` found. ``ok`` only when every check ran and
    passed."""

    dist: str
    sdk: str
    checks: "list[Check]"
    files: "dict[str, str]"

    @property
    def ok(self) -> bool:
        return (len(self.checks) == len(CHECKS)
                and all(check.ok for check in self.checks))

    @property
    def failed(self) -> "list[str]":
        return [check.name for check in self.checks if not check.ok]

    def to_json(self) -> dict:
        return {
            "dist": self.dist,
            "sdk": self.sdk,
            "ok": self.ok,
            "checks": [
                {"name": check.name, "ok": check.ok,
                 "problems": list(check.problems)}
                for check in self.checks
            ],
            "files": dict(sorted(self.files.items())),
        }


def _shown(value) -> str:
    return build._shown(value)


def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


# ------------------------------------------------------------ digest list

_digest_memo: "dict[tuple, dict]" = {}


def _sources_key() -> tuple:
    """A cheap identity for every file the digest list is made from."""
    paths = [build._RUNTIME_JS, build._PEGMENT_CSS, build._AI_JS,
             build._SCAFFOLD_JS, build._EDITOR_JS, build._RTC_JS,
             *build._vendored_fonts()]
    key = []
    for path in paths:
        try:
            info = path.stat()
            key.append((str(path), info.st_mtime_ns, info.st_size))
        except OSError:
            key.append((str(path), None, None))
    return tuple(key)


def _sdk_digests() -> "dict[str, str]":
    """``{published path: sha256}`` of every file this SDK owns in a dist."""
    key = _sources_key()
    if key not in _digest_memo:
        bundles = build._sdk_bundles(minify=True, rtc=True)
        files = {name: _sha256(text.encode("utf-8"))
                 for name, text in bundles.items() if text}
        for font in build._vendored_fonts():
            files["fonts/" + font.name] = _sha256(font.read_bytes())
        _digest_memo.clear()
        _digest_memo[key] = dict(sorted(files.items()))
    return dict(_digest_memo[key])


#: Files in the digest list a build writes only when the page needs them.
_OPTIONAL = frozenset({"rtc.js"})


def digest_list() -> dict:
    """The installed SDK's digest list, as ``workpeg ui verify --digests``
    prints it: the record a builder image writes of the files it owns."""
    from workpeg import target_sdk

    sheet = None
    if build._icons_source_key() is not None:
        sheet = _sha256(build._read_icons_source().encode("utf-8"))
    return {
        "format": 1,
        "sdk": target_sdk.installed(),
        "files": _sdk_digests(),
        "optional": sorted(_OPTIONAL),
        "icons_sheet": sheet,
    }


# -------------------------------------------------------------- the target

def _check_target(sdk: str) -> None:
    """Refuse a target this SDK cannot check for: any but itself."""
    from workpeg import function_base, target_sdk

    here = target_sdk.installed()
    if sdk != here:
        raise VerifyError(
            f"This computer has SDK {here}, and it holds the digest list and "
            f"the page template of {here} only, so it cannot check a dist "
            f"for SDK {sdk}. Check it with the verifier of {sdk} "
            f"(`pip install workpeg=={sdk}`), or check a build made with "
            f"{here}.")
    if function_base.RELEASE.fullmatch(sdk):
        try:
            target_sdk.check(sdk)
        except target_sdk.TargetError:
            raise VerifyError(
                f"SDK {sdk} is below {target_sdk.FLOOR}, the first release "
                f"whose builds carry the script policy, and Workpeg passes "
                f"no build below it.") from None


# ------------------------------------------------------------------- read

def _name_problem(rel: str) -> "str | None":
    """Why *rel* cannot be a name in a dist, or None."""
    if not rel or rel.startswith("/") or "\\" in rel:
        return "it is not a relative path inside the dist."
    if len(rel) > 1024:
        return "its name is longer than 1024 characters."
    for part in rel.split("/"):
        if part in ("", ".", ".."):
            return "it is not a plain path inside the dist (an empty, . or .. part)."
        if len(part) > 255:
            return "a part of its name is longer than 255 characters."
        if not all(0x20 <= ord(ch) < 0x7f for ch in part):
            return ("its name holds a character outside printable ASCII, so "
                    "it can read as a different name than it is.")
        if build._URL_SYNTAX.search(part):
            return ("its name holds a character that means something in a URL "
                    "(: ? # ; % \\), so it can be served as a type its suffix "
                    "does not say.")
    return None


class _Reader:
    """Collects the files of a dist within the caps, and why any entry was
    refused."""

    def __init__(self) -> None:
        self.files: "dict[str, bytes]" = {}
        self.folders: "set[str]" = set()
        self.problems: "list[str]" = []
        self.entries = 0
        self.size = 0
        self.full = False
        self._folded: "dict[str, str]" = {}

    def refuse(self, rel: str, why: str) -> None:
        self.problems.append(f"{_shown(rel)}: {why}")

    def count(self, rel: str) -> bool:
        """Count one entry, and claim its name. False when it cannot be
        taken (a cap reached, or a name refused)."""
        if self.full:
            return False
        self.entries += 1
        if self.entries > MAX_FILES:
            self.problems.append(
                f"the dist holds more than {MAX_FILES} entries; it is "
                f"refused without reading the rest.")
            self.full = True
            return False
        why = _name_problem(rel)
        if why is not None:
            self.refuse(rel, why)
            return False
        folded = rel.lower()
        if folded in self._folded:
            other = self._folded[folded]
            if other == rel:
                self.refuse(rel, "it is in the dist twice.")
            else:
                self.refuse(rel, (
                    f"it differs only in case from {_shown(other)}, and a "
                    f"disk or a host that ignores case serves one for the "
                    f"other."))
            return False
        self._folded[folded] = rel
        return True

    def budget(self, rel: str, size: int) -> bool:
        if self.size + size > MAX_BYTES:
            self.problems.append(
                f"{_shown(rel)}: the dist's files add up to more than "
                f"{MAX_BYTES} bytes; it is refused without reading the rest.")
            self.full = True
            return False
        self.size += size
        return True


_OPEN_FLAGS = (os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
               | getattr(os, "O_NONBLOCK", 0) | getattr(os, "O_CLOEXEC", 0)
               | getattr(os, "O_BINARY", 0))


def _read_one(path: str, rel: str, info: os.stat_result,
              reader: _Reader) -> None:
    """Read one regular file, refusing it if it is no longer the file the
    walk saw (a swap for a link or a FIFO between the look and the read)."""
    try:
        fd = os.open(path, _OPEN_FLAGS)
    except OSError as exc:
        reader.refuse(rel, f"it cannot be opened without following a link "
                           f"({exc.strerror}).")
        return
    try:
        now = os.fstat(fd)
        if (not stat.S_ISREG(now.st_mode) or now.st_ino != info.st_ino
                or now.st_dev != info.st_dev or now.st_nlink != 1):
            reader.refuse(rel, "it changed while it was being read.")
            return
        if not reader.budget(rel, now.st_size):
            return
        chunks = []
        left = now.st_size + 1
        while left > 0:
            chunk = os.read(fd, min(left, 1 << 20))
            if not chunk:
                break
            chunks.append(chunk)
            left -= len(chunk)
        data = b"".join(chunks)
        if len(data) != now.st_size:
            reader.refuse(rel, "it changed size while it was being read.")
            return
        reader.files[rel] = data
    finally:
        os.close(fd)


def _read_folder(root: str, reader: _Reader) -> None:
    pending = [("", root)]
    while pending and not reader.full:
        rel_dir, path = pending.pop()
        try:
            with os.scandir(path) as it:
                entries = sorted(it, key=lambda entry: entry.name)
        except OSError as exc:
            reader.refuse(rel_dir or ".", (
                f"the folder cannot be opened ({exc.strerror}), so what is in "
                f"it cannot be checked."))
            continue
        for entry in entries:
            rel = f"{rel_dir}/{entry.name}" if rel_dir else entry.name
            if not reader.count(rel):
                if reader.full:
                    return
                continue
            try:
                info = os.lstat(entry.path)
            except OSError as exc:
                reader.refuse(rel, f"it cannot be read ({exc.strerror}).")
                continue
            if stat.S_ISLNK(info.st_mode):
                reader.refuse(rel, (
                    "it is a symbolic link, and the verifier follows none: "
                    "what it points at is not in the dist."))
            elif stat.S_ISDIR(info.st_mode):
                reader.folders.add(rel)
                pending.append((rel, entry.path))
            elif not stat.S_ISREG(info.st_mode):
                reader.refuse(rel, "it is not a regular file (a device, FIFO "
                                   "or socket).")
            elif info.st_nlink != 1:
                reader.refuse(rel, (
                    "it is a hard link, so its bytes may be a file outside "
                    "the dist."))
            else:
                _read_one(entry.path, rel, info, reader)
                if reader.full:
                    return


def _read_tar(path: str, reader: _Reader) -> None:
    # The headers of MAX_FILES entries and their padding, on top of the
    # bytes, and the end-of-archive blocks.
    limit = MAX_BYTES + 1024 * MAX_FILES + 10240
    try:
        size = os.lstat(path).st_size
    except OSError as exc:
        reader.problems.append(f"the tar cannot be read ({exc.strerror}).")
        return
    if size > limit:
        reader.problems.append(
            f"the tar is {size} bytes, more than a dist of {MAX_BYTES} bytes "
            f"can take; it is refused without reading it.")
        return
    try:
        with open(path, "rb") as handle, tarfile.open(
                fileobj=handle, mode="r:") as archive:
            while not reader.full:
                member = archive.next()
                if member is None:
                    break
                _read_member(archive, member, reader)
    except (tarfile.TarError, OSError, EOFError) as exc:
        reader.problems.append(
            f"it is not a plain, whole tar ({_shown(str(exc))}). The verifier "
            f"reads an uncompressed tar or a folder.")


def _header_problem(archive: tarfile.TarFile,
                    member: tarfile.TarInfo) -> "str | None":
    """Why *member*'s headers are refused, or None for a plain ustar header,
    alone or after one PAX header that carries only times.

    A PAX global header, a PAX key beyond the times, and a GNU long-name or
    long-link entry are each a second way of saying a name, a size or where
    an entry ends, which two tar readers can read differently: the one that
    checked a dist and the one that publishes it would see two dists.
    """
    if archive.pax_headers:
        return ("a PAX global header comes before it, which sets fields for "
                "every entry after it; no build writes one.")
    extra = sorted(set(member.pax_headers) - _PAX_TIMES)
    if extra:
        return (f"its PAX header sets {', '.join(map(_shown, extra))}, which "
                f"two tar readers can read differently; only times are "
                f"taken.")
    # Walk the headers between the entry's first block and its data: only
    # PAX extended headers may be there, never a GNU L or K entry.
    handle = archive.fileobj
    at, end = member.offset, member.offset_data - tarfile.BLOCKSIZE
    while at < end:
        handle.seek(at)
        block = handle.read(tarfile.BLOCKSIZE)
        kind = block[156:157]
        if kind in (tarfile.GNUTYPE_LONGNAME, tarfile.GNUTYPE_LONGLINK):
            return ("its name or link comes from a GNU long-name entry, "
                    "which two tar readers can read as two different "
                    "names.")
        if kind != tarfile.XHDTYPE or len(block) != tarfile.BLOCKSIZE:
            return "a header the verifier does not read comes before it."
        try:
            size = tarfile.nti(block[124:136])
        except tarfile.InvalidHeaderError:
            return "a header before it has no readable size."
        at += tarfile.BLOCKSIZE + -(-size // tarfile.BLOCKSIZE) * (
            tarfile.BLOCKSIZE)
    if at != end:
        return "its headers do not end where its data begins."
    return None


def _read_member(archive: tarfile.TarFile, member: tarfile.TarInfo,
                 reader: _Reader) -> None:
    name = member.name
    if name.startswith("./"):
        name = name[2:]
    name = name.rstrip("/") if member.isdir() else name
    if name in ("", "."):
        if member.isdir():
            return
    if not reader.count(name):
        return
    why = _header_problem(archive, member)
    if why is not None:
        reader.refuse(name, why)
        return
    if member.isdir():
        reader.folders.add(name)
        return
    if member.issym() or member.islnk():
        reader.refuse(name, "it is a link, and the verifier follows none.")
        return
    if not member.isreg() or member.issparse():
        reader.refuse(name, "it is not a regular file (a device, FIFO or "
                            "sparse file).")
        return
    if not reader.budget(name, member.size):
        return
    handle = archive.extractfile(member)
    data = handle.read(member.size + 1) if handle is not None else b""
    if len(data) != member.size:
        reader.refuse(name, "it is shorter than its header says.")
        return
    reader.files[name] = data


def _read(dist: str) -> _Reader:
    reader = _Reader()
    try:
        info = os.lstat(dist)
    except OSError as exc:
        raise VerifyError(f"{_shown(dist)} cannot be read: {exc.strerror}.")
    if stat.S_ISLNK(info.st_mode):
        reader.problems.append(
            f"{_shown(dist)} is a symbolic link, and the verifier follows "
            f"none. Pass the folder or the tar itself.")
    elif stat.S_ISDIR(info.st_mode):
        _read_folder(dist, reader)
    elif stat.S_ISREG(info.st_mode):
        _read_tar(dist, reader)
    else:
        reader.problems.append(
            f"{_shown(dist)} is neither a folder nor a tar.")
    # A folder that holds a file of a name seen as both is refused by count;
    # one seen only as a folder of an SDK file's name is refused below.
    return reader


# ------------------------------------------------------------------ files

def _files_problems(files: "dict[str, bytes]", folders: "set[str]",
                    digests: "dict[str, str]") -> "list[str]":
    owned = _PAGE_FILES | set(digests) | _OPTIONAL
    reserved = {name.lower() for name in owned | build._BUILD_WRITES}
    problems = []
    for folder in sorted(folders):
        if folder.lower() in reserved:
            problems.append(f"{_shown(folder)}: it is a folder with the name "
                            f"of a file the build writes.")
    for rel in sorted(files):
        if rel in owned:
            continue
        parts = rel.split("/")
        base = parts[-1]
        suffix = os.path.splitext(base)[1].lower()
        if len(parts) == 1 and rel.lower() in reserved:
            why = ("it differs only in case from a file the build writes, "
                   "and a host that ignores case serves one for the other.")
        elif base.lower() in build._PROJECT_CONFIG_NAMES:
            why = "it is a project's config, which no build ships."
        elif suffix in (".html", ".htm", ".xhtml", ".shtml"):
            why = "index.html is the only page a dist may hold."
        elif suffix in (".js", ".mjs", ".cjs", ".wasm"):
            why = ("a peg is Python only: the only scripts on a page are the "
                   "SDK's own, at the names its digest list gives.")
        elif suffix in (".css", ".svg", ".svgz", ".xml"):
            why = (f"a browser can run or style a page from {suffix}, and the "
                   f"SDK writes the only ones a dist holds.")
        elif suffix == ".pdf":
            why = ("a PDF is refused until a PDF's script has been measured "
                   "(decision 15), as the CDN refuses it.")
        elif suffix in _SHIPPABLE:
            continue
        else:
            why = (f"a dist cannot hold {suffix or 'a file with no suffix'}: "
                   f"only types measured inert ship.")
        problems.append(f"{_shown(rel)}: {why}")
    return problems


# ------------------------------------------------------------- build.json

def _no_duplicate_keys(pairs):
    seen = {}
    for key, value in pairs:
        if key in seen:
            raise ValueError(f"the key {key!r} is in it twice")
        seen[key] = value
    return seen


def _record_problems(files: "dict[str, bytes]", sdk: str,
                     namespace: "str | None") -> "tuple[dict | None, list]":
    """``(page inputs, problems)``. The inputs are None unless every one of
    them is of the shape the build writes."""
    data = files.get("build.json")
    if data is None:
        return None, ["build.json is missing: the build writes it, and "
                      "without it nothing says what made this dist."]
    if len(data) > MAX_RECORD_BYTES:
        return None, [f"build.json is {len(data)} bytes, more than the "
                      f"{MAX_RECORD_BYTES} a build's record can take."]
    try:
        record = json.loads(data.decode("utf-8"),
                            object_pairs_hook=_no_duplicate_keys)
    except (UnicodeDecodeError, ValueError, RecursionError) as exc:
        return None, [f"build.json is not JSON: {_shown(str(exc))}."]
    if not isinstance(record, dict) or set(record) != _RECORD_KEYS:
        return None, ["build.json holds keys other than format, sdk and "
                      "page, or not all of them."]
    problems = []
    fmt = record["format"]
    if type(fmt) is not int or fmt != build.BUILD_RECORD_FORMAT:
        problems.append(f"build.json is format {_shown(json.dumps(fmt))}, and "
                        f"this SDK reads format "
                        f"{build.BUILD_RECORD_FORMAT}.")
    if record["sdk"] != sdk:
        problems.append(
            f"build.json says SDK {_shown(json.dumps(record['sdk']))} built "
            f"it, not {sdk}, the target it is checked against.")
    page = record["page"]
    if not isinstance(page, dict) or set(page) != _PAGE_KEYS:
        problems.append("build.json's page holds inputs other than the ones "
                        "the page is made from, or not all of them.")
        return None, problems
    for key in ("app_name", "peg_namespace", "icons_href", "icons_ver",
                "chrome_source", "ver"):
        if not isinstance(page[key], str):
            problems.append(f"build.json's page.{key} is not a string.")
    for key in _BOOL_KEYS:
        if type(page[key]) is not bool:
            problems.append(f"build.json's page.{key} is not true or false.")
    fonts = page["fonts"]
    if fonts is not None and (not isinstance(fonts, list) or not all(
            build._font_url_allowed(url) for url in fonts)):
        problems.append("build.json's page.fonts is not a list of the web "
                        "font URLs a peg may link.")
    if problems:
        return None, problems
    if page["chrome_source"] != "auto":
        problems.append(
            f"build.json says the chrome is "
            f"{_shown(json.dumps(page['chrome_source']))}. A released peg "
            f"loads its chrome from the CDN first, and is never built with "
            f"--chrome bundled.")
    if not _HASH8.fullmatch(page["ver"]):
        problems.append("build.json's page.ver is not the build's 8-character "
                        "hash.")
    if page["icons_href"] not in (build.ICONS_HREF, build.ICONS_CDN):
        problems.append(
            f"build.json's page links the icon sheet "
            f"{_shown(page['icons_href'])}, which is neither the build's own "
            f"{build.ICONS_HREF} nor the SDK's CDN copy.")
    if page["icons_ver"] and not _VERSIONISH.fullmatch(page["icons_ver"]):
        problems.append("build.json's page.icons_ver is not a version.")
    if len(page["app_name"]) > 256 or len(page["peg_namespace"]) > 64:
        problems.append("build.json's page names an app or a peg longer than "
                        "any build writes.")
    if namespace is not None and page["peg_namespace"] != namespace:
        problems.append(
            f"build.json says the page is peg "
            f"{_shown(json.dumps(page['peg_namespace']))}, not {namespace}.")
    return (None if problems else page), problems


# ----------------------------------------------------------------- inputs

def _bundle_hash(files: "dict[str, bytes]") -> str:
    """The build's ``?v=``: the first 8 of a sha1 over app.js and the SDK's
    bundles, in the order the build hashes them."""
    names = ("app.js", "workpeg-runtime.js", "pegment.css", "ai.js",
             "scaffold.js", "editor.js", "rtc.js")
    return hashlib.sha1(
        b"".join(files.get(name, b"") for name in names)).hexdigest()[:8]


def _inputs_problems(files: "dict[str, bytes]",
                     page: "dict | None") -> "list[str]":
    if page is None:
        return ["there are no page inputs to compare: build.json is refused."]
    problems = []
    ver = _bundle_hash(files)
    if page["ver"] != ver:
        problems.append(
            f"the page's ?v= is {page['ver']}, and the files hash to {ver}, so "
            f"they are not the files the page was built with.")
    has_rtc = "rtc.js" in files
    if page["uses_rtc"] != has_rtc:
        problems.append(
            "build.json says the page uses WebRTC and there is no rtc.js."
            if page["uses_rtc"] else
            "there is an rtc.js and build.json says the page does not use "
            "WebRTC, so nothing would load it as the page's own.")
    has_icons = "icons.css" in files
    if page["icons_href"] == build.ICONS_HREF:
        if not page["uses_icons"] or not has_icons:
            problems.append("the page links /icons.css, and the dist has no "
                            "icons.css or the page draws no icon.")
        elif page["icons_ver"] != hashlib.sha1(
                files["icons.css"]).hexdigest()[:8]:
            problems.append("icons.css is not the sheet the page's link "
                            "names.")
    else:
        if has_icons:
            problems.append("there is an icons.css and the page links the "
                            "CDN's sheet, so nothing links this one.")
        want = build._icons_version(False) if page["uses_icons"] else ""
        if page["icons_ver"] != want:
            problems.append(
                f"the page links the CDN's icon sheet at version "
                f"{_shown(page['icons_ver'] or 'none')}, and this SDK links "
                f"{want or 'none'}.")
    return problems


# ------------------------------------------------------------- index.html

def _index_problems(files: "dict[str, bytes]",
                    page: "dict | None") -> "list[str]":
    data = files.get("index.html")
    if data is None:
        return ["index.html is missing."]
    if page is None:
        return ["there are no page inputs to make index.html from: "
                "build.json is refused."]
    if len(data) > MAX_PAGE_BYTES:
        return [f"index.html is {len(data)} bytes, and no build writes a "
                f"page over {MAX_PAGE_BYTES}."]
    want = build._gen_html(**page).encode("utf-8")
    if data == want:
        return []
    at = next((i for i, (a, b) in enumerate(zip(data, want)) if a != b),
              min(len(data), len(want)))
    seen = data[max(0, at - 20):at + 40].decode("utf-8", "replace")
    return [f"index.html is not what this SDK writes for its inputs. They "
            f"part at byte {at}, at {_shown(seen)}."]


# ------------------------------------------------------------------- page

#: The attributes each element of a page may carry, and nothing else.
_ALLOWED_ATTRS = {
    "html": {"lang"},
    "head": set(),
    "meta": {"charset", "http-equiv", "content", "name"},
    "link": {"rel", "href", "crossorigin"},
    "title": set(),
    "body": set(),
    "div": {"id"},
    "script": {"src"},
}
_META_NAMES = {"viewport", "peg-namespace"}
_PRECONNECT = {
    "https://cdn.workpeg.com", "https://fonts.googleapis.com",
    "https://fonts.gstatic.com",
}


class _PageReader(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.events: "list[tuple]" = []
        self.open: "list[str]" = []

    def handle_starttag(self, tag, attrs):
        self.events.append(("start", tag, attrs, tuple(self.open)))
        if tag not in ("meta", "link"):
            self.open.append(tag)

    def handle_startendtag(self, tag, attrs):
        self.events.append(("start", tag, attrs, tuple(self.open)))

    def handle_endtag(self, tag):
        if self.open and self.open[-1] == tag:
            self.open.pop()
        else:
            self.events.append(("stray", tag))

    def handle_data(self, data):
        if data.strip():
            self.events.append(("data", data, tuple(self.open)))

    def handle_comment(self, data):
        self.events.append(("other", "a comment"))

    def handle_decl(self, decl):
        self.events.append(("decl", decl))

    def unknown_decl(self, data):
        self.events.append(("other", "a declaration"))

    def handle_pi(self, data):
        self.events.append(("other", "a processing instruction"))


def _page_problems(files: "dict[str, bytes]") -> "list[str]":
    """The page's markup, read without trusting the template that made it,
    so it holds for a target whose ``_gen_html`` cannot be called."""
    data = files.get("index.html")
    if data is None:
        return ["index.html is missing."]
    if len(data) > MAX_PAGE_BYTES:
        return [f"index.html is {len(data)} bytes, and no build writes a "
                f"page over {MAX_PAGE_BYTES}; it is refused unread."]
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return ["index.html is not UTF-8."]
    reader = _PageReader()
    reader.feed(text)
    reader.close()
    problems = []
    policies = 0
    scripts = []
    head = []
    for event in reader.events:
        kind = event[0]
        if kind == "decl":
            if event[1].lower() != "doctype html" or reader.events[0] != event:
                problems.append("index.html has a declaration other than its "
                                "opening <!DOCTYPE html>.")
            continue
        if kind in ("other", "stray"):
            problems.append(f"index.html holds {_shown(event[1])}, which no "
                            f"build writes.")
            continue
        if kind == "data":
            if event[2][-1:] != ("title",):
                problems.append(f"index.html holds text outside its title: "
                                f"{_shown(event[1][:40])}.")
            continue
        _, tag, attrs, parents = event
        names = [name for name, _ in attrs]
        values = {name: (value or "") for name, value in attrs}
        if tag not in _ALLOWED_ATTRS:
            problems.append(f"index.html has a <{_shown(tag)}>, which no build "
                            f"writes.")
            continue
        if "data-chrome" in names:
            problems.append("index.html loads its chrome with data-chrome: a "
                            "released peg is never built with --chrome "
                            "bundled.")
        for name in names:
            if name.startswith("on"):
                problems.append(f"index.html has an inline handler "
                                f"({_shown(name)}) on <{tag}>.")
            elif name not in _ALLOWED_ATTRS[tag] and name != "data-chrome":
                problems.append(f"index.html's <{tag}> has {_shown(name)}, "
                                f"which no build writes.")
        if len(set(names)) != len(names):
            problems.append(f"index.html's <{tag}> names an attribute twice.")
        if parents[-1:] == ("head",) and tag in ("meta", "link"):
            head.append((tag, values))
        if tag == "meta":
            equiv = values.get("http-equiv")
            if equiv is not None:
                if equiv.lower() != "content-security-policy":
                    problems.append(f"index.html has a <meta http-equiv="
                                    f"{_shown(equiv)}>, which no build "
                                    f"writes.")
                    continue
                policies += 1
                if values.get("content") != build.SCRIPT_POLICY:
                    problems.append(
                        f"index.html's script policy is "
                        f"{_shown(values.get('content'))}, not the SDK's "
                        f"SCRIPT_POLICY.")
            elif "name" in values and values["name"] not in _META_NAMES:
                problems.append(f"index.html has a <meta name="
                                f"{_shown(values['name'])}>, which no build "
                                f"writes.")
        elif tag == "link":
            problems.extend(_link_problems(values))
        elif tag == "script":
            scripts.append((values.get("src"), parents))
        elif tag == "div" and values.get("id") != "workpeg-root":
            problems.append("index.html has a <div> other than the app's "
                            "root.")
    if policies != 1:
        problems.append(f"index.html carries {policies} script policies; "
                        f"every build carries exactly one.")
    if len(head) < 2 or [tag for tag, _ in head[:2]] != ["meta", "meta"] or (
            "charset" not in head[0][1]) or (
            head[1][1].get("http-equiv", "").lower()
            != "content-security-policy"):
        problems.append("index.html's script policy is not the first thing "
                        "after its charset, so what comes before it is not "
                        "governed by it.")
    problems.extend(_script_problems(scripts, "rtc.js" in files))
    return problems


def _link_problems(values: "dict[str, str]") -> "list[str]":
    rel, href = values.get("rel"), values.get("href", "")
    if rel == "preconnect":
        if href in _PRECONNECT:
            return []
    elif rel == "stylesheet":
        if re.fullmatch(r"/pegment\.css(\?v=[0-9a-f]{8})?", href):
            return []
        if re.fullmatch(r"/icons\.css(\?v=[0-9A-Za-z.+-]+)?", href):
            return []
        if href.startswith(build.ICONS_CDN) and re.fullmatch(
                r"(\?v=[0-9A-Za-z.+-]+)?", href[len(build.ICONS_CDN):]):
            return []
        if build._font_url_allowed(href):
            return []
    return [f"index.html links {_shown(href)} as {_shown(rel)}, which no "
            f"build links."]


def _script_problems(scripts, has_rtc: bool) -> "list[str]":
    srcs = [src for src, _ in scripts]
    vers = {src.split("?v=", 1)[1] for src in srcs
            if src and "?v=" in src}
    ver = vers.pop() if len(vers) == 1 else "<ver>"
    want = ["/workpeg-runtime.js", *(["/rtc.js"] if has_rtc else []),
            "/app.js"]
    want = [f"{name}?v={ver}" for name in want]
    problems = []
    if srcs != want or not _HASH8.fullmatch(ver):
        problems.append(
            f"index.html loads {_shown(srcs)}; a build loads exactly "
            f"/workpeg-runtime.js, then /rtc.js when the dist carries it, "
            f"then /app.js, each with the same ?v= hash.")
    if any(parents[-1:] != ("body",) for _, parents in scripts):
        problems.append("index.html has a script outside its body.")
    return problems


# -------------------------------------------------------------- sdk files

def _sdk_file_problems(files: "dict[str, bytes]",
                       digests: "dict[str, str]") -> "list[str]":
    problems = []
    for name, want in sorted(digests.items()):
        data = files.get(name)
        if data is None:
            if name not in _OPTIONAL:
                problems.append(f"{_shown(name)} is missing; every build of "
                                f"this SDK writes it.")
            continue
        got = _sha256(data)
        if got != want:
            problems.append(
                f"{_shown(name)} is not this SDK's: sha256 {got}, and the "
                f"digest list says {want}.")
    return problems


# -------------------------------------------------------------- icons.css

_RULE = re.compile(r"([^{}]+)\{([^{}]*)\}")
_sheet_memo: "dict[tuple, frozenset]" = {}


def _sheet_rules() -> "frozenset[str] | None":
    key = build._icons_source_key()
    if key is None:
        return None
    if key not in _sheet_memo:
        rules = frozenset(match.group(0) for match in
                          _RULE.finditer(build._read_icons_source()))
        _sheet_memo.clear()
        _sheet_memo[key] = rules
    return _sheet_memo[key]


def _rules(text: str) -> "list[str]":
    """The rules *text* starts with, one after another, up to the first
    text that is not a rule. Matched at each next offset only: trying the
    pattern from every offset, as ``finditer`` does, is quadratic on text
    with no brace (40 KB took 9.7 s), and this is linear."""
    rules = []
    at = 0
    while at < len(text):
        match = _RULE.match(text, at)
        if match is None:
            break
        rules.append(match.group(0))
        at = match.end()
    return rules


def _icons_problems(files: "dict[str, bytes]") -> "list[str]":
    data = files.get("icons.css")
    if data is None:
        return []
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return ["icons.css is not UTF-8."]
    sheet = _sheet_rules()
    if sheet is None:
        return ["this SDK has no icon sheet to compare icons.css with, so it "
                "cannot pass it."]
    rules = _rules(text)
    problems = []
    if sum(map(len, rules)) != len(text):
        problems.append("icons.css holds text between or around its rules "
                        "(an @import or a stray declaration, say), which no "
                        "icon sheet has.")
    strange = [rule for rule in rules if rule not in sheet]
    for rule in strange[:5]:
        problems.append(f"icons.css has a rule this SDK's icon sheet does "
                        f"not: {_shown(rule[:80])}.")
    if len(strange) > 5:
        problems.append(f"...and {len(strange) - 5} more such rules.")
    return problems


# ----------------------------------------------------------------- app.js

def _app_problems(files: "dict[str, bytes]") -> "list[str]":
    data = files.get("app.js")
    if data is None:
        return ["app.js is missing."]
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return ["app.js is not UTF-8."]
    problems = []
    for name, pattern in _SINKS:
        found = pattern.search(text)
        if found:
            seen = text[max(0, found.start() - 30):found.end() + 30]
            problems.append(
                f"app.js names {name}, which compiled Python never needs "
                f"(at {_shown(seen)}). If it is a word in your app's text, "
                f"spell it another way.")
    problems.extend(_node_check(data))
    return problems


def _node_check(data: bytes) -> "list[str]":
    """``node --check`` on a copy the verifier wrote, so a hostile name never
    reaches a command line. Fails closed: a check that could not run is not
    a check that passed."""
    node = shutil.which("node")
    if node is None:
        return ["node is not installed here, so whether app.js parses cannot "
                "be checked, and the verifier passes nothing it could not "
                "check. Install node."]
    with tempfile.TemporaryDirectory(prefix="workpeg-verify-") as folder:
        path = os.path.join(folder, "app.js")
        with open(path, "wb") as handle:
            handle.write(data)
        try:
            result = subprocess.run(
                [node, "--check", path], capture_output=True, text=True,
                timeout=_NODE_TIMEOUT, stdin=subprocess.DEVNULL)
        except (OSError, subprocess.TimeoutExpired) as exc:
            return [f"node could not check app.js: {_shown(str(exc))}."]
    if result.returncode != 0:
        first = (result.stderr.strip().splitlines() or [""])
        return [f"app.js does not parse: {_shown(first[-1][:200])}."]
    return []


# ---------------------------------------------------------- manifest.json

def _manifest_problems(files: "dict[str, bytes]") -> "list[str]":
    data = files.get("manifest.json")
    if data is None:
        return []
    if len(data) > build.MAX_MANIFEST_BYTES:
        return [f"manifest.json is {len(data)} bytes; the platform reads none "
                f"over {build.MAX_MANIFEST_BYTES}."]
    try:
        manifest = json.loads(data.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, RecursionError) as exc:
        return [f"manifest.json is not JSON: {_shown(str(exc))}."]
    if not isinstance(manifest, dict):
        return ["manifest.json is not a JSON object."]
    return []


# ----------------------------------------------------------------- verify

def verify(dist: "str | Path", sdk: str, *,
           namespace: "str | None" = None) -> Report:
    """Check the dist folder or tar at *dist* as SDK *sdk*'s build. Raises
    :class:`VerifyError` when *sdk* is not the SDK installed here."""
    _check_target(sdk)
    dist = os.fspath(dist)
    digests = _sdk_digests()
    reader = _read(dist)
    files = reader.files
    page, record = _record_problems(files, sdk, namespace)
    checks = [
        Check("read", reader.problems),
        Check("files", _files_problems(files, reader.folders, digests)),
        Check("build.json", record),
        Check("inputs", _inputs_problems(files, page)),
        Check("index.html", _index_problems(files, page)),
        Check("page", _page_problems(files)),
        Check("sdk files", _sdk_file_problems(files, digests)),
        Check("icons.css", _icons_problems(files)),
        Check("app.js", _app_problems(files)),
        Check("manifest.json", _manifest_problems(files)),
    ]
    return Report(
        dist=dist, sdk=sdk, checks=checks,
        files={name: _sha256(data) for name, data in files.items()},
    )


def render(report: Report) -> str:
    """The report as ``workpeg ui verify`` prints it."""
    lines = [f"Checking {_shown(report.dist)} as a build of SDK {report.sdk}"]
    for check in report.checks:
        lines.append(f"  {'ok  ' if check.ok else 'FAIL'}  {check.name}")
        lines.extend(f"        {problem}" for problem in check.problems)
    if report.ok:
        lines.append(f"{_shown(report.dist)} passes all {len(CHECKS)} checks "
                     f"for SDK {report.sdk}.")
    else:
        lines.append(f"{_shown(report.dist)} fails {len(report.failed)} of "
                     f"{len(CHECKS)} checks ({', '.join(report.failed)}). "
                     f"Nothing in it may go live.")
    return "\n".join(lines)
